from __future__ import annotations

from datetime import date
from enum import Enum
from dataclasses import dataclass
from typing import Any
from sqlalchemy.orm import Session
from sqlalchemy import tuple_, desc, or_

from app.models.academic.SubjectLoad import SubjectLoad
from app.models.academic.TeacherSubstitution import TeacherSubstitution
from app.models.academic.Subject import Subject
from app.models.people.AcademicStaff import AcademicStaff

# Explicit legacy seed subject IDs generated by SeedLivePredictions.py (not in DepEd curriculum subject_load catalog)
LEGACY_IMPORT_SUBJECT_IDS = frozenset(range(18, 33))  # 18 through 32


class TeacherStatusLabel(str, Enum):
    ASSIGNED = "ASSIGNED"
    SUBSTITUTE_ACTIVE = "SUBSTITUTE_ACTIVE"
    NO_CONFIRMED_TEACHER = "NO_CONFIRMED_TEACHER"
    HISTORICAL_UNMAPPED = "HISTORICAL_UNMAPPED"
    UNASSIGNED = "UNASSIGNED"


class TeacherResolutionError(RuntimeError):
    """Raised when the batch teacher resolver fails to satisfy its lookup contract."""


@dataclass
class TeacherAssignmentInfo:
    is_assigned: bool
    staff_id: str | None = None
    teacher_name: str | None = None
    is_substitute: bool = False
    substitution_id: int | None = None
    substitute_start_date: date | None = None
    substitute_end_date: date | None = None
    original_staff_id: str | None = None
    original_teacher_name: str | None = None
    status_label: TeacherStatusLabel = TeacherStatusLabel.UNASSIGNED


def _format_staff_name(staff: AcademicStaff | None) -> str | None:
    if not staff:
        return None
    first = (staff.first_name or "").strip()
    last = (staff.last_name or "").strip()
    if first and last:
        return f"{first} {last}"
    return first or last or None


def resolve_teachers_for_loads(
    db: Session,
    triplets: list[tuple[int, int, int]],  # (class_id, subject_id, academic_period_id)
    as_of: date | None = None,
) -> dict[tuple[int, int, int], TeacherAssignmentInfo]:
    """Batched canonical resolver for (class_id, subject_id, academic_period_id) triplets.

    Guarantees fixed O(1) query count (maximum 3 queries) regardless of triplet count.
    Every unique triplet in the input is guaranteed an entry in the returned dict.
    """
    if not triplets:
        return {}
    if as_of is None:
        as_of = date.today()

    unique_triplets = list(set(triplets))
    results: dict[tuple[int, int, int], TeacherAssignmentInfo] = {}

    # Query 1: All active version SubjectLoads for the requested triplets
    loads = (
        db.query(SubjectLoad, AcademicStaff)
        .outerjoin(AcademicStaff, SubjectLoad.staff_id == AcademicStaff.staff_id)
        .filter(
            tuple_(SubjectLoad.class_id, SubjectLoad.subject_id, SubjectLoad.academic_period_id).in_(unique_triplets),
            SubjectLoad.is_active_version == True,
        )
        .order_by(
            SubjectLoad.class_id,
            SubjectLoad.subject_id,
            SubjectLoad.academic_period_id,
            desc(SubjectLoad.updated_at),
            desc(SubjectLoad.subject_load_id),
        )
        .all()
    )

    # Group loads by triplet (taking the most recent active version defensively)
    triplet_to_load: dict[tuple[int, int, int], tuple[SubjectLoad, AcademicStaff | None]] = {}
    for load, staff in loads:
        key = (load.class_id, load.subject_id, load.academic_period_id)
        if key not in triplet_to_load:
            triplet_to_load[key] = (load, staff)

    # Identify confirmed loads that have an assigned staff member
    active_load_ids: list[int] = []
    load_id_to_triplet: dict[int, tuple[int, int, int]] = {}
    for key, (load, staff) in triplet_to_load.items():
        if load.status in ("active", "published") and load.staff_id is not None:
            active_load_ids.append(load.subject_load_id)
            load_id_to_triplet[load.subject_load_id] = key
        else:
            # Tier 2: Load exists, but is draft or staff_id is NULL
            results[key] = TeacherAssignmentInfo(
                is_assigned=False,
                status_label=TeacherStatusLabel.NO_CONFIRMED_TEACHER,
            )

    # Query 2: Active substitutions for any active/published load IDs found
    substitutions_by_load_id: dict[int, tuple[TeacherSubstitution, AcademicStaff, AcademicStaff]] = {}
    if active_load_ids:
        from sqlalchemy.orm import aliased
        SubStaff = aliased(AcademicStaff)
        OrigStaff = aliased(AcademicStaff)

        subs = (
            db.query(TeacherSubstitution, SubStaff, OrigStaff)
            .join(SubStaff, TeacherSubstitution.substitute_staff_id == SubStaff.staff_id)
            .join(OrigStaff, TeacherSubstitution.original_staff_id == OrigStaff.staff_id)
            .filter(
                TeacherSubstitution.subject_load_id.in_(active_load_ids),
                TeacherSubstitution.status == "active",
                TeacherSubstitution.start_date <= as_of,
                or_(
                    TeacherSubstitution.end_date.is_(None),
                    as_of <= TeacherSubstitution.end_date,
                ),
            )
            .order_by(desc(TeacherSubstitution.start_date), desc(TeacherSubstitution.substitution_id))
            .all()
        )
        for sub, sub_staff, orig_staff in subs:
            if sub.subject_load_id not in substitutions_by_load_id:
                substitutions_by_load_id[sub.subject_load_id] = (sub, sub_staff, orig_staff)

    # Populate confirmed assignments (Tier 1: Assigned or Substitute Active)
    for load_id, key in load_id_to_triplet.items():
        load, staff = triplet_to_load[key]
        if load_id in substitutions_by_load_id:
            sub, sub_staff, orig_staff = substitutions_by_load_id[load_id]
            results[key] = TeacherAssignmentInfo(
                is_assigned=True,
                staff_id=sub.substitute_staff_id,
                teacher_name=_format_staff_name(sub_staff),
                is_substitute=True,
                substitution_id=sub.substitution_id,
                substitute_start_date=sub.start_date,
                substitute_end_date=sub.end_date,
                original_staff_id=sub.original_staff_id,
                original_teacher_name=_format_staff_name(orig_staff),
                status_label=TeacherStatusLabel.SUBSTITUTE_ACTIVE,
            )
        else:
            results[key] = TeacherAssignmentInfo(
                is_assigned=True,
                staff_id=load.staff_id,
                teacher_name=_format_staff_name(staff),
                is_substitute=False,
                status_label=TeacherStatusLabel.ASSIGNED,
            )

    # Check remaining unresolved triplets (no SubjectLoad in DB at all)
    unresolved_triplets = [t for t in unique_triplets if t not in results]
    if unresolved_triplets:
        # Query 3: Fetch subjects ONLY for the unresolved triplets to distinguish Tier 3 vs Tier 4
        unresolved_subject_ids = list({t[1] for t in unresolved_triplets})
        known_subjects = {
            s.subject_id: s
            for s in db.query(Subject).filter(Subject.subject_id.in_(unresolved_subject_ids)).all()
        }

        for key in unresolved_triplets:
            subject_id = key[1]
            if subject_id in LEGACY_IMPORT_SUBJECT_IDS:
                results[key] = TeacherAssignmentInfo(
                    is_assigned=False,
                    status_label=TeacherStatusLabel.HISTORICAL_UNMAPPED,
                )
            elif subject_id in known_subjects:
                results[key] = TeacherAssignmentInfo(
                    is_assigned=False,
                    status_label=TeacherStatusLabel.UNASSIGNED,
                )
            else:
                results[key] = TeacherAssignmentInfo(
                    is_assigned=False,
                    status_label=TeacherStatusLabel.HISTORICAL_UNMAPPED,
                )

    return results


def resolve_teacher_for_load(
    db: Session,
    class_id: int,
    subject_id: int,
    academic_period_id: int,
    as_of: date | None = None,
) -> TeacherAssignmentInfo:
    """Single-item delegate calling the batch resolver with a 1-element list.

    Enforces that the batch resolver contract was satisfied for every input triplet.
    """
    triplet = (class_id, subject_id, academic_period_id)
    results = resolve_teachers_for_loads(db, [triplet], as_of=as_of)
    if triplet not in results:
        raise TeacherResolutionError(
            f"resolve_teachers_for_loads contract violated: triplet {triplet} missing from result dict"
        )
    return results[triplet]


def get_teacher_assigned_triplets(
    db: Session,
    staff_id: str,
    academic_period_id: int | None = None,
    as_of: date | None = None,
) -> set[tuple[int, int, int]]:
    """Returns all (class_id, subject_id, academic_period_id) triplets assigned to the teacher.

    Default behavior (academic_period_id is None):
      Scopes across ALL periods the teacher has taught or currently teaches, eliminating
      the discoverability gap between dashboard listing and direct prediction access.

    Filtered behavior (academic_period_id is provided):
      Only scopes to the specific academic_period_id chosen by the teacher in the UI dropdown.
    """
    if as_of is None:
        as_of = date.today()

    # 1. Primary loads where teacher is officially assigned
    primary_query = db.query(
        SubjectLoad.class_id,
        SubjectLoad.subject_id,
        SubjectLoad.academic_period_id,
    ).filter(
        SubjectLoad.staff_id == staff_id,
        SubjectLoad.status.in_(["active", "published"]),
        SubjectLoad.is_active_version == True,
    )
    if academic_period_id is not None:
        primary_query = primary_query.filter(SubjectLoad.academic_period_id == academic_period_id)

    triplets = set(primary_query.all())

    # 2. Substituted loads where teacher is currently acting as substitute
    sub_query = (
        db.query(
            SubjectLoad.class_id,
            SubjectLoad.subject_id,
            SubjectLoad.academic_period_id,
        )
        .join(TeacherSubstitution, TeacherSubstitution.subject_load_id == SubjectLoad.subject_load_id)
        .filter(
            TeacherSubstitution.substitute_staff_id == staff_id,
            TeacherSubstitution.status == "active",
            TeacherSubstitution.start_date <= as_of,
            or_(
                TeacherSubstitution.end_date.is_(None),
                as_of <= TeacherSubstitution.end_date,
            ),
            SubjectLoad.status.in_(["active", "published"]),
            SubjectLoad.is_active_version == True,
        )
    )
    if academic_period_id is not None:
        sub_query = sub_query.filter(SubjectLoad.academic_period_id == academic_period_id)

    triplets.update(sub_query.all())
    return triplets
